$string['setting:risklevelcritical'] = 'El riesgo crítico comienza en';
$string['setting:risklevelcritical_desc'] = 'Las puntuaciones iguales o superiores a este valor se etiquetan como riesgo Crítico. Valor predeterminado: 80.';
$string['setting:risklevelhigh'] = 'El riesgo alto comienza en';
$string['setting:risklevelhigh_desc'] = 'Las puntuaciones iguales o superiores a este valor (y por debajo del límite Crítico) se etiquetan como riesgo Alto. Valor predeterminado: 50.';
$string['setting:risklevelmoderate'] = 'El riesgo moderado comienza en';
$string['setting:risklevelmoderate_desc'] = 'Las puntuaciones iguales o superiores a este valor (y por debajo del límite Alto) se etiquetan como riesgo Moderado; las puntuaciones inferiores son riesgo Bajo. Valor predeterminado: 20.';
$string['setting:risklevelsheading'] = 'Límites de niveles de riesgo';
$string['setting:risklevelsheading_desc'] = 'Límites de puntuación para las etiquetas Bajo / Moderado / Alto / Crítico mostradas en los informes. Los límites nunca se invierten: Alto se limita al límite Crítico y Moderado al límite Alto. Estas etiquetas son solo de presentación; las retenciones de calificación y las reprobaciones automáticas usan el umbral de alto riesgo de la página principal de configuración.';

$string['setting:riskreviewautoreleasedays'] = 'Días de revisión de Student Affairs';
$string['setting:riskreviewautoreleasedays_desc'] = 'Número de días que Student Affairs tiene para confirmar una retención de alto riesgo. Las retenciones activas se liberan automáticamente después de este periodo. Use 0 para desactivar la liberación automática.';
$string['setting:riskreviewenabled'] = 'Retener calificaciones/certificados para intentos de alto riesgo';
$string['setting:riskreviewenabled_desc'] = 'Si está habilitado, los intentos de cuestionarios supervisados con una puntuación de riesgo igual o superior al umbral reciben una retención de revisión con calificación cero hasta que un revisor autorizado la libere. Esto retrasa certificados basados en calificación y aplica tanto si el estudiante aprobó como si reprobó.';
$string['setting:riskreviewthreshold'] = 'Umbral predeterminado de revisión de alto riesgo';
$string['setting:riskreviewthreshold_desc'] = 'Puntuación de riesgo predeterminada de 1 a 100 que activa una retención para revisión administrativa. Los cuestionarios individuales pueden heredar o anular este valor.';
$string['setting:riskscorecapenabled'] = 'Limitar la puntuación de riesgo del intento a 100';
$string['setting:riskscorecapenabled_desc'] = 'Cuando está habilitado (el valor predeterminado), la suma de puntos de los factores se limita a una puntuación máxima de 100. Deshabilítelo para permitir que la puntuación supere 100 cuando se acumulan varios factores. Los umbrales de alto riesgo, los límites de niveles de riesgo y el techo de liberación automática se comparan con el valor sin limitar, y los informes mantienen la etiqueta «puntuación/100», por lo que es posible ver algo como 135/100. Nota: con el límite deshabilitado, establecer el techo de liberación automática en 101 ya no lo desactiva, porque las puntuaciones realmente pueden alcanzarlo.';
$string['setting:screensharepersistencemode'] = 'Modo de persistencia de pantalla compartida';
$string['setting:screensharepersistencemode_auto'] = 'Automático: mantener la pantalla compartida en la ventana auxiliar en escritorio';
$string['setting:screensharepersistencemode_desc'] = 'Controla si la pantalla compartida de escritorio ocurre en la página principal del cuestionario o en la ventana auxiliar. Un flujo de pantalla compartida está vinculado a la página que lo inició, por lo que compartir en la página principal se interrumpe en cada navegación del cuestionario y se vuelve a solicitar al estudiante en cada página. Automático usa la ventana auxiliar en escritorio para que la pantalla compartida sobreviva a los cambios de página y la captura de escritorio permanezca activa independientemente de la política de monitores múltiples; elija la página principal solo si acepta esa nueva solicitud en cada página.';
